import 'dart:io';
import 'api_service.dart';

/// Secure HttpOverrides specifically scoped to the designated Kanvtech office server
/// and local loopback development environments.
///
/// This permits self-signed TLS certificates generated by Caddy on the office server
/// (192.168.1.4:8444) without disabling certificate validation globally for arbitrary third-party hosts.
class OfficeServerHttpOverrides extends HttpOverrides {
  static bool isPermittedHost(String host, int port,
      {String? configuredBaseUrl}) {
    // 1. Authorized designated office server
    if (host == '192.168.1.4' && (port == 8444 || port == 0)) {
      return true;
    }

    // 2. Local loopback / Android emulator
    if (host == '127.0.0.1' || host == '10.0.2.2' || host == 'localhost') {
      return true;
    }

    // 3. User configured base URL host/port
    final baseUrl = configuredBaseUrl ?? ApiService().baseUrl;
    try {
      final uri = Uri.parse(baseUrl);
      if (uri.host.isNotEmpty && host == uri.host) {
        final expectedPort = uri.hasPort ? uri.port : 8444;
        if (port == expectedPort || port == 0) {
          return true;
        }
      }
    } catch (_) {}

    // Strictly reject all other arbitrary hosts to preserve TLS integrity
    return false;
  }

  @override
  HttpClient createHttpClient(SecurityContext? context) {
    final client = super.createHttpClient(context);
    client.badCertificateCallback =
        (X509Certificate cert, String host, int port) {
      if (!isPermittedHost(host, port)) return false;
      final now = DateTime.now();
      if (now.isBefore(cert.startValidity) || now.isAfter(cert.endValidity)) {
        return false;
      }
      return true;
    };
    return client;
  }
}
